--
-- TOC entry 248 (class 1259 OID 25146)
-- Name: expanded_keywords; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.expanded_keywords AS
 SELECT DISTINCT r.id,
    r.label,
    public.unaccent(lower(TRIM(BOTH FROM word.word))) AS mot_clef
   FROM public.ref_formation r,
    LATERAL unnest(r.mots_clefs) mot_clef(mot_clef),
    LATERAL unnest(string_to_array((mot_clef.mot_clef)::text, ' '::text)) word(word)
  WHERE ((r.obsolete = false) AND (length(TRIM(BOTH FROM word.word)) >= 2));


--
-- TOC entry 249 (class 1259 OID 25151)
-- Name: expanded_label; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.expanded_label AS
 SELECT DISTINCT ref_formation.id,
    ref_formation.label,
    public.unaccent(lower(TRIM(BOTH FROM ref_formation.label))) AS label_sans_accents,
    public.unaccent(lower(TRIM(BOTH FROM label_decoupe_brut.label_decoupe_brut))) AS label_decoupe
   FROM public.ref_formation,
    LATERAL unnest(string_to_array(regexp_replace((ref_formation.label)::text, '[^0-9A-Za-zÀ-ÖØ-öø-ÿ]+'::text, ' '::text, 'g'::text), ' '::text)) label_decoupe_brut(label_decoupe_brut)
  WHERE ((length(label_decoupe_brut.label_decoupe_brut) >= 2) AND (ref_formation.obsolete = false));


